  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f5f6fa;
  --color-surface: #ffffff;
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-primary-active: #3730a3;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-border: #e5e7eb;
  --color-border-focus: #4f46e5;
  --color-radio-selected-bg: #ede9fe;
  --color-radio-selected-border: #4f46e5;
  --color-success-bg: #ecfdf5;
  --color-success-border: #10b981;
  --color-success-text: #065f46;
  --radius-card: 16px;
  --radius-option: 10px;
  --radius-btn: 10px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --transition: 0.18s ease;
}

body {
  min-height: 100vh;
  background: var(--color-bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--color-text);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-primary);
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-btn);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 16px;
}

main {
  width: 100%;
  max-width: 520px;
}

.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 40px 40px 36px;
}

.card-header {
  margin-bottom: 32px;
}

.card-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 12px;
}

.card-eyebrow svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}

.card-title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}

.card-subtitle {
  margin-top: 6px;
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* Form field wrapper */
.form-field {
  margin-bottom: 28px;
}

.form-field legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 14px;
  float: left;
  width: 100%;
}

/* Radio options */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  clear: both;
}

.radio-option {
  position: relative;
}

.radio-option input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.radio-option label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-option);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  user-select: none;
}

.radio-option label:hover {
  border-color: var(--color-border-focus);
  background: #f5f3ff;
}

/* Custom radio indicator */
.radio-indicator {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
}

.radio-indicator::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: transparent;
  transition: background var(--transition);
}

.radio-option-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--color-bg);
  flex-shrink: 0;
  transition: background var(--transition);
}

.radio-option-icon svg {
  width: 18px;
  height: 18px;
  fill: var(--color-text-muted);
  transition: fill var(--transition);
}

.radio-label-text {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
}

/* Checked state */
.radio-option input[type="radio"]:checked + label {
  border-color: var(--color-radio-selected-border);
  background: var(--color-radio-selected-bg);
  box-shadow: 0 0 0 1px var(--color-radio-selected-border);
}

.radio-option input[type="radio"]:checked + label .radio-indicator {
  border-color: var(--color-primary);
  background: var(--color-primary);
}

.radio-option input[type="radio"]:checked + label .radio-indicator::after {
  background: #fff;
}

.radio-option input[type="radio"]:checked + label .radio-option-icon {
  background: #ddd6fe;
}

.radio-option input[type="radio"]:checked + label .radio-option-icon svg {
  fill: var(--color-primary);
}

/* Focus-visible on label */
.radio-option input[type="radio"]:focus-visible + label {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Submit button */
.btn-submit {
  width: 100%;
  padding: 14px 24px;
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-btn);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), transform 0.1s ease, box-shadow var(--transition);
  letter-spacing: 0.01em;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.28);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.38);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 3px;
}

/* Success message */
.status-message {
  margin-top: 18px;
  padding: 14px 16px;
  border-radius: var(--radius-option);
  font-size: 0.9375rem;
  font-weight: 500;
  display: none;
}

.status-message.success {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  color: var(--color-success-text);
}

.status-message svg {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  fill: #10b981;
}

/* Error hint */
.error-hint {
  margin-top: 8px;
  font-size: 0.875rem;
  color: #dc2626;
  display: none;
}

.form-field[data-error="true"] .error-hint {
  display: block;
}

.form-field[data-error="true"] .radio-group {
  border-radius: var(--radius-option);
  outline: 2px solid #dc2626;
  outline-offset: 4px;
}

/* Responsive */
@media (max-width: 480px) {
  .card {
    padding: 28px 20px 24px;
  }
  .card-title {
    font-size: 1.25rem;
  }
}

@media (forced-colors: active) {
  .radio-indicator {
    border-color: ButtonText;
    forced-color-adjust: none;
    background: Canvas;
  }
  .radio-option input[type="radio"]:checked + label .radio-indicator {
    background: Highlight;
    border-color: Highlight;
  }
  .radio-option input[type="radio"]:checked + label .radio-indicator::after {
    background: HighlightText;
  }
  .radio-option label {
    border-color: ButtonText;
  }
  .radio-option input[type="radio"]:checked + label {
    border-color: Highlight;
    outline: 2px solid Highlight;
    background: Canvas;
  }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
    box-shadow: none;
    forced-color-adjust: none;
  }
}
