+const form = document.getElementById('notification-form');
+const formField = document.getElementById('form-field-notification');
+const errorHint = document.getElementById('notification-error');
+const statusMessage = document.getElementById('status-message');
+
+form.addEventListener('submit', (e) => {
+  e.preventDefault();
+
+  const selected = form.querySelector('input[name="notification"]:checked');
+
+  if (!selected) {
+    formField.setAttribute('data-error', 'true');
+    errorHint.setAttribute('aria-live', 'assertive');
+    // Focus the first radio so the user can act immediately
+    form.querySelector('input[name="notification"]').focus();
+    return;
+  }
+
+  formField.removeAttribute('data-error');
+
+  const labelMap = {
+    email: 'Email',
+    sms: 'SMS',
+    push: 'Push Notifications',
+  };
+
+  statusMessage.querySelector('.status-text').textContent =
+    `Preference saved! You'll receive notifications via ${labelMap[selected.value]}.`;
+  statusMessage.classList.add('success');
+  statusMessage.focus();
+});
+
+// Clear error state when user makes a selection
+form.querySelectorAll('input[name="notification"]').forEach((radio) => {
+  radio.addEventListener('change', () => {
+    formField.removeAttribute('data-error');
+  });
+});
+
